function renderRoutes(){$('#routes').innerHTML=EXITS.map(e=>`<button class="route-card ${game?.goal===e.id?'active':''}" data-route="${e.id}" aria-label="${e.name}の脱出条件"><div class="route-head"><span class="route-icon" style="color:${e.color}">${e.icon}</span><span>${e.en}</span></div><h3>${e.name}</h3><div class="route-tag"><b>${e.tag}</b><span>${e.risk}</span></div><div class="route-need">${Object.entries(e.need).map(([k,v])=>`<span style="color:${RES[k].color}">${RES[k].icon} ${RES[k].label} ${v}</span>`).join('')}</div></button>`).join('');$$('[data-route]').forEach(b=>b.onclick=()=>showRoute(b.dataset.route))}
