function insideRing(x,y,ring){let inside=false;for(let i=0,j=ring.length-1;i<ring.length;j=i++){const a=ring[i],b=ring[j];if((a[1]>y)!==(b[1]>y)&&x<(b[0]-a[0])*(y-a[1])/(b[1]-a[1])+a[0])inside=!inside}return inside}
function tileIntersectsKanto(c){const size=256;const nw=map.unproject([c.x*size,c.y*size],c.z),se=map.unproject([(c.x+1)*size,(c.y+1)*size],c.z);const points=[[nw.lng,nw.lat],[se.lng,nw.lat],[se.lng,se.lat],[nw.lng,se.lat],[(nw.lng+se.lng)/2,(nw.lat+se.lat)/2]];return boundaries.features.some(f=>f.geometry.coordinates.some(poly=>{const ring=poly[0];return points.some(([x,y])=>insideRing(x,y,ring))||ring.some(([x,y])=>x>=nw.lng&&x<=se.lng&&y<=nw.lat&&y>=se.lat)}))}
function nodeIcon(n){const here=game?.players.filter(p=>p.pos===n.id)||[],reach=game?neighbors(game.players[game.turn].pos).some(e=>e.to===n.id):false;const major=n.exit||['kinshicho','shinjuku','ueno','tachikawa','okutama','kashiwa','chiba','mito','utsunomiya','takasaki'].includes(n.id),show=(map?.getZoom()>=11.5)||major||here.length||selected===n.id;return L.divIcon({className:'node-wrap',html:`<button tabindex="-1" class="node-btn ${n.exit?'exit':''} ${selected===n.id?'selected':''} ${reach?'reachable':''} ${game?.searched.includes(n.id)?'searched':''}" aria-label="${n.name}"><span class="node-point"></span>${show?`<span class="node-label">${n.name}</span>`:''}${here.length?`<span class="player-pips">${here.map(p=>`<span class="player-pip" style="background:${ROLES[p.role].color}">${p.id+1}</span>`).join('')}</span>`:''}</button>`,iconSize:[1,1],iconAnchor:[0,0]})}
function updateMap(){if(!map){if($('#map-fallback svg'))fallbackMap();return}NODES.forEach(n=>markers[n.id]?.setIcon(nodeIcon(n)));if(game){const p=game.players[game.turn];$('.map-note').innerHTML=`<span>ROUND ${String(game.round).padStart(2,'0')} / TEAM POSITION</span><strong>${escape(p.name)} / ${NODE[p.pos].name}</strong><small>明るい地点を選んで、次の一歩を。</small>`}lines.forEach(({line,edge:e})=>{line.setStyle({opacity:game&&[e.a,e.b].includes(game.players[game.turn].pos)?.95:.48,color:e.type==='loop'&&game&&EVENTS[game.event].kind==='blackout'?'#a56d65':e.type==='loop'?'#9ac98e':['mountain','foot'].includes(e.type)?'#e8b96e':'#7ea7a0'})})}
function fallbackMap(){const el=$('#map-fallback');el.hidden=false;const project=n=>[50+(n.lng-138.9)*430,420-(n.lat-35.35)*300];el.innerHTML=`<svg viewBox="0 0 850 530" role="img" aria-label="関東の簡略ルート地図"><defs><pattern id="grid" width="30" height="30" patternUnits="userSpaceOnUse"><path d="M30 0H0V30" fill="none" stroke="#29423a" stroke-width=".5"/></pattern></defs><rect width="850" height="530" fill="url(#grid)"/>${EDGES.map(e=>{const a=project(NODE[e.a]),b=project(NODE[e.b]);return `<path d="M${a}L${b}" fill="none" stroke="${e.type==='loop'?'#94be81':'#698e80'}" stroke-width="2" ${e.type==='mountain'?'stroke-dasharray="5 5"':''}/>`}).join('')}${NODES.map(n=>{const[x,y]=project(n);return `<g class="fallback-node" data-map-node="${n.id}" tabindex="0" role="button" aria-label="${n.name}" transform="translate(${x},${y})"><circle r="${n.exit?7:4}"/><text x="9" y="4">${n.name}</text></g>`}).join('')}</svg>`;$$('[data-map-node]').forEach(b=>{b.onclick=()=>selectNode(b.dataset.mapNode);b.onkeydown=e=>{if(e.key==='Enter')selectNode(b.dataset.mapNode)}});$('#map-status').textContent='簡略ルート地図 / 地図ライブラリを読み込めませんでした。'}
$('#focus-btn').onclick=focusPlayer;$('#overview-btn').onclick=()=>map?.fitBounds([[34.96,138.55],[37.15,140.91]],{padding:[20,20]});$('#base-btn').onclick=()=>{if(!map||!base)return;baseOn=!baseOn;if(baseOn)base.addTo(map);else base.remove();$('#base-btn').textContent=`地形 ${baseOn?'ON':'OFF'}`;$('#base-btn').setAttribute('aria-pressed',String(baseOn))};
$('#rules-btn').onclick=()=>showModal(`<span class="eyebrow">HOW TO PLAY</span><h2>全員で、東京の外へ。</h2><p>謎の封鎖によって交通が少しずつ止まっていく東京。東東京・錦糸町から、仲間全員で脱出するターン制ゲームです。</p><ol><li><strong>探索して物資を集める。</strong> 食料・乗車券・山装備・通信機は全員で共有。各地点はチームで1回だけ探索できます。</li><li><strong>1人ずつ、2回行動。</strong> 移動・探索・休息はそれぞれ1行動。「交代」を押すと次の人へ。全員が行動すると1ラウンドが終わり、1人につき食料を1消費します。</li><li><strong>鉄道か、徒歩か。</strong> 鉄道は乗車券を消費。徒歩は体力を2消費します。山道は体力を4消費し、山装備が1つ以上必要。休息は食料1で体力を4回復します。</li><li><strong>同じ出口に、全員集合。</strong> 5つのルートから出口を選び、必要な物資をそろえると「全員で脱出」が押せます。最後のラウンド中までに脱出しましょう。</li></ol><h3>4つの役割</h3><p>${ROLES.map(r=>`${r.icon} <strong>${r.name}</strong>：${r.perk}`).join('<br>')}</p><h3>協力プレイ</h3><p>1台の端末を1〜4人で交代して遊べます。「オンライン協力」ではルームコードを使って最大4端末で参加できます。ホストはプレイ中も画面を開いたままにしてください。</p><p class="network-tip">難易度は探索30・標準24・極限18ラウンド。途中経過は端末に自動保存されます。地図の接続はゲーム用の簡略表現で、実際の運行情報や登山ルートではありません。</p>`);
$('#credits-btn').onclick=()=>showModal(`<span class="eyebrow">DATA & CREDITS</span><h2>関東の地図から、物語を。</h2><p>舞台は東京都・神奈川県・埼玉県・千葉県・茨城県・栃木県・群馬県の7都県。全国の地図を読み込まず、関東に絞った境界ファイルを読み込みます。東京の離島は今回の舞台に含めていません。</p><h3>地理データ</h3><p><a href="https://maps.gsi.go.jp/development/ichiran.html" target="_blank" rel="noopener">国土地理院・地理院タイル（淡色地図）</a>をインターネットから表示。タイルは関東の境界と重なるものだけを取得し、表示範囲も関東に制限しています。タイルは矩形のため、県境の近くに隣県の一部が写ることがあります。Shoreline data: VMAP0, USGS (1997).</p><p>都県境界：<a href="https://github.com/dataofjapan/land" target="_blank" rel="noopener">Data of Japan / land</a>（元データ：国土数値情報、関東7都県のみ抽出・簡略化）。</p><h3>ライブラリ</h3><p><a href="https://leafletjs.com" target="_blank" rel="noopener">Leaflet 1.9.4</a>（BSD-2-Clause） / <a href="https://peerjs.com" target="_blank" rel="noopener">PeerJS 1.5.5</a>（MIT）。ライセンス全文は<a href="licenses.txt" target="_blank" rel="noopener">こちら</a>。</p><h3>ゲーム内の設定</h3><p>実在の地名を使ったフィクションです。路線は簡略化され、運休・封鎖・救援便・物資・移動時間はすべて架空です。実際の避難や移動案内には使えません。</p>`);

// The room host alone applies actions. Each connection is bound to one player slot.
function networkStatus(text){const el=$('#network-status');if(el)el.textContent=text}
function disconnect(){clearTimeout(networkTimeout);if(peer){peer.destroy();peer=null}connections.clear();online=null;lobby=[];localSlot=0}
function makeCode(){const a='ABCDEFGHJKLMNPQRSTUVWXYZ23456789';const nums=crypto.getRandomValues(new Uint8Array(7));return Array.from(nums,n=>a[n%a.length]).join('')}
function showNetwork(){if(online){showRoomInfo();return}showModal(`<span class="eyebrow">ONLINE CO-OP / 1—4 PLAYERS</span><h2>離れていても、同じチーム。</h2><p>ホストがルームを作り、7文字のコードを仲間に伝えてください。参加者ごとに別の端末・ブラウザで開きます。</p><label class="field-label" for="net-name">あなたの名前</label><input class="form-input" id="net-name" maxlength="16" value="" placeholder="プレイヤー"><label class="field-label" for="net-role">役割</label><select class="form-input" id="net-role">${ROLES.map((r,i)=>`<option value="${i}">${r.name} — ${r.perk}</option>`).join('')}</select><div class="modal-actions"><button class="primary" id="create-room">ルームを作る ↗</button></div><label class="field-label" for="join-code" style="display:block;margin-top:20px">ルームコードで参加</label><input id="join-code" class="form-input" maxlength="7" placeholder="例：ABCD234" autocomplete="off" style="text-transform:uppercase"><button class="secondary full" id="join-room">仲間のルームに参加 →</button><div id="network-status" role="status"></div><p class="network-tip">PeerJSの公開接続サービスを使用します。回線によって接続できない場合は、1台での協力プレイをご利用ください。このサイトの閲覧権限がある人同士で利用できます。通信中はホストの画面を開いたままにしてください。${game?'現在の遠征は保存したまま、新しい遠征を開始します。':''}</p>`);$('#create-room').onclick=()=>createRoom($('#net-name').value,+$('#net-role').value);$('#join-room').onclick=()=>joinRoom($('#join-code').value,$('#net-name').value,+$('#net-role').value)}
$('#online-btn').onclick=showNetwork;
function peerError(err){clearTimeout(networkTimeout);const msgs={'peer-unavailable':'そのルームが見つかりません。コードとホストの接続を確認してください。','network':'接続サービスに届きません。ネットワークを確認してください。','unavailable-id':'コードが重複しました。もう一度ルームを作成してください。','webrtc':'端末間の接続ができません。この回線では1台での協力プレイをご利用ください。'};const msg=msgs[err.type]||'接続に失敗しました。通信環境を確認し、ルームを開き直してください。';networkStatus(msg);toast(msg);if(!game||!online?.started)disconnect()}
function beginPeer(id){if(!window.Peer){toast('通信ライブラリを読み込めません。1台での協力プレイを利用できます。');return null}const p=id?new Peer(id,{debug:0}):new Peer({debug:0});p.on('error',peerError);networkTimeout=setTimeout(()=>{networkStatus('接続がタイムアウトしました。ルームを開き直してください。');toast('ルームへの接続がタイムアウトしました。');if(!online?.started)disconnect()},20000);return p}
function createRoom(name,role){disconnect();networkStatus('接続サービスにルームを作っています…');const code=makeCode();online={isHost:true,code,started:false};lobby=[{slot:0,name:name.trim().slice(0,16)||'ホスト',role}];peer=beginPeer('tokyo-escape-v1-'+code);if(!peer){online=null;return}peer.on('open',()=>{clearTimeout(networkTimeout);showLobby()});peer.on('connection',conn=>{if(online?.started||lobby.length>=4){conn.on('open',()=>{conn.send({type:'reject',message:online?.started?'この遠征は開始済みです。':'このルームは4人で満員です。'});setTimeout(()=>conn.close(),300)});return}let boundSlot=null;conn.on('data',msg=>{if(!online?.isHost||!msg||typeof msg!=='object')return;if(msg.type==='hello'&&boundSlot===null&&!online.started){const slot=[1,2,3].find(s=>!lobby.some(p=>p.slot===s));if(slot===undefined){conn.send({type:'reject',message:'このルームは満員です。'});return}boundSlot=slot;conn.gameSlot=slot;connections.set(slot,conn);lobby.push({slot,name:String(msg.name||`プレイヤー ${slot+1}`).trim().slice(0,16),role:Number.isInteger(msg.role)&&msg.role>=0&&msg.role<4?msg.role:slot});lobby.sort((a,b)=>a.slot-b.slot);broadcastLobby();showLobby()}else if(msg.type==='action'&&online.started&&game?.status==='playing'&&conn.gameSlot===game.turn){if(JSON.stringify(msg.action||{}).length<500)applyAction(msg.action||{})}});conn.on('close',()=>{if(boundSlot===null)return;connections.delete(conn.gameSlot);if(!online?.started){lobby=lobby.filter(p=>p.slot!==boundSlot);broadcastLobby();if(online?.isHost)showLobby()}else{toast(`${game.players[conn.gameSlot]?.name||'仲間'}が切断されました。ホストが代わりに操作できます。`);if(game)renderGame()}});conn.on('error',()=>toast('仲間の端末との通信に問題が発生しました。'))})}
function broadcastLobby(){connections.forEach((conn,slot)=>conn.open&&conn.send({type:'lobby',lobby,slot,code:online.code}))}
function joinRoom(code,name,role){code=code.toUpperCase().replace(/\s/g,'');if(!/^[A-HJ-NP-Z2-9]{7}$/.test(code)){networkStatus('7文字のルームコードを入力してください。');return}disconnect();networkStatus('仲間のルームに接続しています…');online={isHost:false,code,started:false};peer=beginPeer();if(!peer){online=null;return}peer.on('open',()=>{const conn=peer.connect('tokyo-escape-v1-'+code,{reliable:true});online.hostConnection=conn;conn.on('open',()=>conn.send({type:'hello',name:name.trim().slice(0,16)||'ゲスト',role}));conn.on('data',msg=>{if(!msg||typeof msg!=='object')return;if(msg.type==='reject'){networkStatus(msg.message);toast(msg.message);disconnect()}else if(msg.type==='lobby'&&Array.isArray(msg.lobby)){clearTimeout(networkTimeout);localSlot=msg.slot;lobby=msg.lobby;showLobby()}else if(msg.type==='state'&&validGame(msg.state)){clearTimeout(networkTimeout);online.started=true;localSlot=msg.slot;game=msg.state;selected=game.players[game.turn].pos;save();closeModal();render();if(game.turn===localSlot)focusPlayer()}});conn.on('close',()=>{if(!online)return;toast('ホストとの接続が切れました。保存データから1台で続きを遊べます。');const started=online.started;disconnect();if(started&&game)render();else showNetwork()});conn.on('error',peerError)})}
function showLobby(){if(!online||online.started)return;showModal(`<span class="eyebrow">TEAM LOBBY</span><h2>仲間の合流を待とう。</h2><p>仲間に、この7文字のコードを伝えてください。</p><div class="room-code">${escape(online.code)}</div><div class="room-members">${lobby.map((p,i)=>`<div class="room-member"><span style="color:${ROLES[p.role]?.color}">${escape(p.name)}</span><small>${ROLES[p.role]?.name} / ${i===0?'HOST':'JOINED'}</small></div>`).join('')}</div><p>${lobby.length} / 4人が参加中</p>${online.isHost?`<label class="field-label" for="net-difficulty">難易度</label><select class="form-input" id="net-difficulty"><option value="easy">探索 / 30ラウンド</option><option value="normal" selected>標準 / 24ラウンド</option><option value="hard">極限 / 18ラウンド</option></select><button class="primary" id="start-online">${lobby.length}人で出発する ↗</button>`:'<p class="waiting">ホストが遠征を開始すると、自動的に地図へ移ります。</p>'}<div class="modal-actions"><button class="secondary" id="copy-code">コードをコピー</button><button class="secondary" id="cancel-room">ルームを離れる</button></div><div id="network-status"></div><p class="network-tip">1〜4人で開始できます。開始後の途中参加はできません。ホストは切断された仲間のキャラクターも操作できます。</p>`);$('#copy-code').onclick=async()=>{try{await navigator.clipboard.writeText(online.code);toast('ルームコードをコピーしました。')}catch{toast('表示されたコードを選択してコピーしてください。')}};$('#cancel-room').onclick=()=>{disconnect();closeModal()};if($('#start-online'))$('#start-online').onclick=startOnline}
function startOnline(){const sorted=[...lobby].sort((a,b)=>a.slot-b.slot),oldConnections=new Map(connections);connections.clear();sorted.forEach((p,i)=>{if(oldConnections.has(p.slot)){const c=oldConnections.get(p.slot);c.gameSlot=i;connections.set(i,c)}p.slot=i});lobby=sorted;game=createGame(lobby.length,$('#net-difficulty').value,lobby.map(p=>p.name),lobby.map(p=>p.role));online.started=true;selected='kinshicho';save();broadcastState();closeModal();render();focusPlayer()}
function broadcastState(){if(!online?.isHost||!game)return;connections.forEach((c,slot)=>{if(c.open)c.send({type:'state',state:game,slot})})}
function showRoomInfo(){if(!online){showNetwork();return}if(!online.started){showLobby();return}showModal(`<span class="eyebrow">CONNECTED TEAM</span><h2>同じ地図の上で。</h2><div class="room-code">${escape(online.code)}</div><p>あなたは ${online.isHost?'ホスト':'プレイヤー '+(localSlot+1)}。行動順が回ってきたプレイヤーが操作します。ホストは、接続が切れた仲間の操作を引き継げます。</p><p class="network-tip">遠征開始後の途中参加・再接続はできません。通信をやめる場合は「遠征を保存して戻る」を選択してください。最後に同期した遠征を1台で再開できます。</p>`)}
window.addEventListener('beforeunload',save);
render();initMap();
